function protoChain(obj) {
  const out = []
  for (let p = Object.getPrototypeOf(obj); p !== null; p = Object.getPrototypeOf(p)) out.push(p)
  return out
}
function findOwner(obj, key) {
  for (let o = obj; o !== null; o = Object.getPrototypeOf(o)) if (Object.hasOwn(o, key)) return o
  return null
}

