function withEvents(obj) {
  const map = new Map()
  return {
    ...obj,
    on(name, fn) { map.set(name, [...(map.get(name) ?? []), fn]) },
    emit(name, ...args) { for (const fn of map.get(name) ?? []) fn(...args) },
  }
}

