function validated(schema) {
  return new Proxy({}, {
    set(t, k, v) {
      if (!(k in schema)) throw new Error('unknown key')
      if (typeof v !== schema[k]) throw new TypeError(`${String(k)} must be ${schema[k]}`)
      return Reflect.set(t, k, v)
    },
  })
}
